25	    private static matches(event: KeyboardEvent, binding: KeyboardShortcut) {
26	        const applePlatform = isApplePlatform()
27	        const expectedCtrl = binding.ctrl || (binding.mod && !applePlatform)
28	        const expectedMeta = binding.mod && applePlatform
29	
30	        return event.key.toLowerCase() === binding.key.toLowerCase()
31	            && event.ctrlKey === expectedCtrl
32	            && event.metaKey === expectedMeta
33	            && event.shiftKey === binding.shift
34	            && event.altKey === binding.alt
35	    }
