37	    register(binding: KeyboardShortcutBinding) {
38	        if (this.bindings.has(binding.id)) throw new Error(`Keyboard shortcut already registered: ${binding.id}`)
39	
40	        this.bindings.set(binding.id, binding)
41	        if (this.bindings.size === 1) {
42	            this.listenerTarget = window
43	            this.listenerTarget.addEventListener('keydown', this.handleKeyDown)
44	        }
45	
